-- Version 1: initial schema.
--
-- Conventions
--   * Dates of diary data are local calendar dates stored as 'YYYY-MM-DD' text.
--   * Nutrition columns (kcal … sodium) are per 100 g / 100 mL and are never
--     rounded. NULL means "unknown", which is different from 0.
--   * Ids are UUIDs generated by the app, so a retried request can never
--     create a duplicate row.

CREATE TABLE settings (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL                      -- JSON
) STRICT;

CREATE TABLE auth (
  id         INTEGER PRIMARY KEY CHECK (id = 1),
  pin_hash   TEXT NOT NULL,
  updated_at TEXT NOT NULL
) STRICT;

CREATE TABLE sessions (
  token_hash   TEXT PRIMARY KEY,           -- SHA-256 of the cookie value
  created_at   TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  expires_at   TEXT NOT NULL,
  user_agent   TEXT
) STRICT;

-- Targets are kept with the date they started applying, so changing a goal
-- today does not rewrite the goal shown on past days.
CREATE TABLE target_history (
  effective_from TEXT PRIMARY KEY
    CHECK (effective_from GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  targets        TEXT NOT NULL,            -- JSON {kcal, protein_g, carbs_g, fat_g, weekdays?}
  created_at     TEXT NOT NULL
) STRICT;

CREATE TABLE foods (
  id          TEXT PRIMARY KEY,
  source      TEXT NOT NULL CHECK (source IN ('custom', 'off', 'usda', 'recipe')),
  source_id   TEXT,                        -- barcode (off) or FDC id (usda)
  name        TEXT NOT NULL,
  brand       TEXT,
  barcode     TEXT,
  base_unit   TEXT NOT NULL DEFAULT 'g' CHECK (base_unit IN ('g', 'ml')),
  kcal        REAL CHECK (kcal IS NULL OR kcal >= 0),
  protein     REAL CHECK (protein IS NULL OR protein >= 0),
  carbs       REAL CHECK (carbs IS NULL OR carbs >= 0),
  fat         REAL CHECK (fat IS NULL OR fat >= 0),
  fibre       REAL CHECK (fibre IS NULL OR fibre >= 0),
  sugar       REAL CHECK (sugar IS NULL OR sugar >= 0),
  sat_fat     REAL CHECK (sat_fat IS NULL OR sat_fat >= 0),
  sodium      REAL CHECK (sodium IS NULL OR sodium >= 0),   -- mg
  servings    TEXT NOT NULL DEFAULT '[]',  -- JSON [{label, amount}] in base units
  last_unit_label  TEXT,                   -- the serving used last time, for one-tap re-logging
  last_unit_amount REAL,
  last_quantity    REAL,
  is_favourite INTEGER NOT NULL DEFAULT 0 CHECK (is_favourite IN (0, 1)),
  use_count    INTEGER NOT NULL DEFAULT 0,
  last_used_at TEXT,
  recipe_servings      REAL,               -- recipes only
  recipe_cooked_weight REAL,               -- recipes only, optional
  search_text  TEXT NOT NULL,              -- lower-case name + brand
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL,
  deleted_at   TEXT
) STRICT;

CREATE INDEX foods_barcode ON foods (barcode) WHERE barcode IS NOT NULL;
CREATE UNIQUE INDEX foods_source_key ON foods (source, source_id) WHERE source_id IS NOT NULL;
CREATE INDEX foods_recent ON foods (last_used_at) WHERE last_used_at IS NOT NULL;

CREATE TABLE recipe_ingredients (
  id          TEXT PRIMARY KEY,
  recipe_id   TEXT NOT NULL REFERENCES foods (id) ON DELETE CASCADE,
  food_id     TEXT REFERENCES foods (id) ON DELETE SET NULL,
  position    INTEGER NOT NULL,
  name        TEXT NOT NULL,
  brand       TEXT,
  base_unit   TEXT NOT NULL CHECK (base_unit IN ('g', 'ml')),
  unit_label  TEXT NOT NULL,
  unit_amount REAL NOT NULL CHECK (unit_amount > 0),
  quantity    REAL NOT NULL CHECK (quantity > 0),
  amount      REAL NOT NULL CHECK (amount > 0),
  kcal REAL, protein REAL, carbs REAL, fat REAL, fibre REAL, sugar REAL, sat_fat REAL, sodium REAL
) STRICT;

CREATE INDEX recipe_ingredients_recipe ON recipe_ingredients (recipe_id, position);

-- Each diary entry carries a snapshot of the food as it was when logged.
-- Editing or deleting the food later does not change past days.
CREATE TABLE diary_entries (
  id          TEXT PRIMARY KEY,
  date        TEXT NOT NULL CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  meal        INTEGER NOT NULL CHECK (meal BETWEEN 0 AND 3),
  food_id     TEXT REFERENCES foods (id) ON DELETE SET NULL,
  kind        TEXT NOT NULL DEFAULT 'food' CHECK (kind IN ('food', 'quick')),
  name        TEXT NOT NULL,
  brand       TEXT,
  base_unit   TEXT NOT NULL CHECK (base_unit IN ('g', 'ml')),
  unit_label  TEXT NOT NULL,
  unit_amount REAL NOT NULL CHECK (unit_amount > 0),
  quantity    REAL NOT NULL CHECK (quantity > 0),
  amount      REAL NOT NULL CHECK (amount > 0),   -- unit_amount x quantity
  kcal REAL, protein REAL, carbs REAL, fat REAL, fibre REAL, sugar REAL, sat_fat REAL, sodium REAL,
  servings    TEXT NOT NULL DEFAULT '[]',         -- snapshot of the serving options
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  deleted_at  TEXT                                -- set by delete, cleared by undo
) STRICT;

CREATE INDEX diary_entries_date ON diary_entries (date, meal);

CREATE TABLE exercise_entries (
  id           TEXT PRIMARY KEY,
  date         TEXT NOT NULL CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  name         TEXT NOT NULL,
  activity_key TEXT,
  minutes      REAL NOT NULL CHECK (minutes >= 0),
  kcal         REAL NOT NULL CHECK (kcal >= 0),
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL
) STRICT;

CREATE INDEX exercise_entries_date ON exercise_entries (date);

CREATE TABLE days (
  date     TEXT PRIMARY KEY CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  water_ml REAL NOT NULL DEFAULT 0 CHECK (water_ml >= 0),
  note     TEXT NOT NULL DEFAULT ''
) STRICT;

CREATE TABLE weights (
  date       TEXT PRIMARY KEY CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  kg         REAL NOT NULL CHECK (kg > 0),
  updated_at TEXT NOT NULL
) STRICT;

CREATE TABLE measurements (
  id         TEXT PRIMARY KEY,
  date       TEXT NOT NULL CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  kind       TEXT NOT NULL,
  value      REAL NOT NULL CHECK (value > 0),
  updated_at TEXT NOT NULL,
  UNIQUE (date, kind)
) STRICT;

CREATE TABLE saved_meals (
  id           TEXT PRIMARY KEY,
  name         TEXT NOT NULL,
  use_count    INTEGER NOT NULL DEFAULT 0,
  last_used_at TEXT,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL
) STRICT;

CREATE TABLE saved_meal_items (
  id            TEXT PRIMARY KEY,
  saved_meal_id TEXT NOT NULL REFERENCES saved_meals (id) ON DELETE CASCADE,
  food_id       TEXT REFERENCES foods (id) ON DELETE SET NULL,
  position      INTEGER NOT NULL,
  kind          TEXT NOT NULL DEFAULT 'food' CHECK (kind IN ('food', 'quick')),
  name          TEXT NOT NULL,
  brand         TEXT,
  base_unit     TEXT NOT NULL CHECK (base_unit IN ('g', 'ml')),
  unit_label    TEXT NOT NULL,
  unit_amount   REAL NOT NULL CHECK (unit_amount > 0),
  quantity      REAL NOT NULL CHECK (quantity > 0),
  amount        REAL NOT NULL CHECK (amount > 0),
  kcal REAL, protein REAL, carbs REAL, fat REAL, fibre REAL, sugar REAL, sat_fat REAL, sodium REAL,
  servings      TEXT NOT NULL DEFAULT '[]'
) STRICT;

CREATE INDEX saved_meal_items_meal ON saved_meal_items (saved_meal_id, position);

-- Foods seen in online search results, kept briefly so a result can be saved
-- to `foods` on first use without asking the online source again.
CREATE TABLE online_cache (
  source     TEXT NOT NULL,
  source_id  TEXT NOT NULL,
  data       TEXT NOT NULL,                -- JSON, already normalised
  fetched_at TEXT NOT NULL,
  PRIMARY KEY (source, source_id)
) STRICT;
